-- =====================================================================
-- FORMULARIOS (tipo Google Forms) para jugadores
-- =====================================================================
-- Ejecutar completo en Supabase > SQL Editor. Es idempotente.
--
--   forms             -> formularios creados por el staff (textos {es,it,en})
--   form_assignments  -> a qué jugadores se envía cada formulario
--   form_responses    -> una respuesta por jugador y formulario
--
-- Permisos:
--   staff   -> todo
--   jugador -> lee los formularios que le han enviado (publicados o cerrados)
--              y crea/edita SU respuesta mientras el formulario esté publicado
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.forms (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  title JSONB NOT NULL DEFAULT '{}'::jsonb,
  description JSONB NOT NULL DEFAULT '{}'::jsonb,
  questions JSONB NOT NULL DEFAULT '[]'::jsonb,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'closed')),
  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL DEFAULT auth.uid(),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.form_assignments (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  form_id UUID NOT NULL REFERENCES public.forms(id) ON DELETE CASCADE,
  player_id UUID NOT NULL REFERENCES public.players(id) ON DELETE CASCADE,
  assigned_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (form_id, player_id)
);

CREATE TABLE IF NOT EXISTS public.form_responses (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  form_id UUID NOT NULL REFERENCES public.forms(id) ON DELETE CASCADE,
  player_id UUID NOT NULL REFERENCES public.players(id) ON DELETE CASCADE,
  answers JSONB NOT NULL DEFAULT '{}'::jsonb,
  submitted_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (form_id, player_id)
);

CREATE INDEX IF NOT EXISTS form_assignments_player_idx ON public.form_assignments(player_id);
CREATE INDEX IF NOT EXISTS form_responses_player_idx ON public.form_responses(player_id);

-- RLS
ALTER TABLE public.forms ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.form_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.form_responses ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS staff_all ON public.forms;
DROP POLICY IF EXISTS staff_all ON public.form_assignments;
DROP POLICY IF EXISTS staff_all ON public.form_responses;
CREATE POLICY staff_all ON public.forms            FOR ALL TO authenticated USING (public.is_staff()) WITH CHECK (public.is_staff());
CREATE POLICY staff_all ON public.form_assignments FOR ALL TO authenticated USING (public.is_staff()) WITH CHECK (public.is_staff());
CREATE POLICY staff_all ON public.form_responses   FOR ALL TO authenticated USING (public.is_staff()) WITH CHECK (public.is_staff());

DROP POLICY IF EXISTS player_read ON public.forms;
CREATE POLICY player_read ON public.forms FOR SELECT TO authenticated USING (
  status <> 'draft' AND EXISTS (
    SELECT 1 FROM public.form_assignments a WHERE a.form_id = forms.id AND a.player_id = public.my_player_id()
  )
);

DROP POLICY IF EXISTS player_read ON public.form_assignments;
CREATE POLICY player_read ON public.form_assignments FOR SELECT TO authenticated
  USING (player_id = public.my_player_id());

-- Formulario enviado a este jugador y abierto (publicado)
CREATE OR REPLACE FUNCTION public.form_open_for_me(fid uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.forms f
    JOIN public.form_assignments a ON a.form_id = f.id
    WHERE f.id = fid AND f.status = 'published' AND a.player_id = public.my_player_id()
  );
$$;

DROP POLICY IF EXISTS player_read ON public.form_responses;
DROP POLICY IF EXISTS player_insert ON public.form_responses;
DROP POLICY IF EXISTS player_update ON public.form_responses;
CREATE POLICY player_read ON public.form_responses FOR SELECT TO authenticated
  USING (player_id = public.my_player_id());
CREATE POLICY player_insert ON public.form_responses FOR INSERT TO authenticated
  WITH CHECK (player_id = public.my_player_id() AND public.form_open_for_me(form_id));
CREATE POLICY player_update ON public.form_responses FOR UPDATE TO authenticated
  USING (player_id = public.my_player_id() AND public.form_open_for_me(form_id))
  WITH CHECK (player_id = public.my_player_id() AND public.form_open_for_me(form_id));

