INSERT INTO public.forms (id, title, description, questions, status)
VALUES ('5e1f0a00-0000-4000-8000-000000000001', $json${"es": "Cuestionario de autoevaluación y desarrollo", "it": "Questionario di autovalutazione e sviluppo", "en": "Self-assessment and development questionnaire"}$json$::jsonb, $json${"es": "En este cuestionario encontrarás nueve áreas donde analizarás tu rendimiento. Debes seleccionar una opción en cada área (nivel). Además, tendrás la oportunidad de reflexionar sobre cada área y explicar tus ideas, sugerencias, emociones o necesidades personales.", "it": "In questo questionario troverai nove aree in cui analizzerai le tue prestazioni. Devi selezionare un'opzione in ciascuna area (livello). Inoltre, avrai l'opportunità di riflettere su ogni area ed esprimere le tue idee, suggerimenti, emozioni o necessità personali.", "en": "In this questionnaire you will find nine areas in which you will analyse your performance. You must select one option in each area (level). You will also have the opportunity to reflect on each area and explain your ideas, suggestions, emotions or personal needs."}$json$::jsonb, $json$[{"id": "a1_s", "type": "section", "title": {"es": "1. Adaptación", "it": "1. Adattamento", "en": "1. Adaptation"}, "description": {"es": "Participación y eficacia en diferentes áreas o posiciones en el campo. Ejecución de intenciones individuales y colectivas, considerando la situación de juego (características del jugador, del oponente y los momentos específicos del partido).", "it": "Partecipazione ed efficacia in diverse aree o posizioni in campo. Esecuzione di intenzioni individuali e collettive, considerando la situazione di gioco (caratteristiche del giocatore, dell'avversario e momenti specifici della partita).", "en": "Participation and effectiveness in different areas or positions on the pitch. Execution of individual and collective intentions, considering the game situation (characteristics of the player, the opponent and specific moments of the match)."}}, {"id": "a1_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a1_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador participa sin ofrecer alternativas, mostrando resistencia e ineficacia al jugar en diferentes espacios/ubicaciones.", "it": "Il giocatore partecipa senza offrire alternative, mostrando resistenza e inefficacia quando gioca in spazi/posizioni differenti.", "en": "The player participates without offering alternatives, showing resistance and ineffectiveness when playing in different spaces/positions."}, "score": 1}, {"id": "a1_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador participa en diferentes espacios/ubicaciones a veces, cuando le ayudan los entrenadores y/o compañeros, aplicando soluciones con eficacia irregular.", "it": "Il giocatore partecipa a volte in spazi/posizioni differenti, quando aiutato da allenatori e/o compagni, applicando soluzioni con efficacia irregolare.", "en": "The player sometimes participates in different spaces/positions when helped by coaches and/or teammates, applying solutions with irregular effectiveness."}, "score": 2}, {"id": "a1_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador participa en diferentes espacios/ubicaciones con apoyo ocasional de entrenadores y/o compañeros, experimentando soluciones con eficacia regular.", "it": "Il giocatore partecipa in spazi/posizioni differenti con il supporto occasionale di allenatori e/o compagni, sperimentando soluzioni con efficacia regolare.", "en": "The player participates in different spaces/positions with occasional support from coaches and/or teammates, trying solutions with regular effectiveness."}, "score": 3}, {"id": "a1_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador participa en diferentes espacios/ubicaciones por iniciativa propia, encontrando soluciones con eficacia y proponiéndolas a sus compañeros.", "it": "Il giocatore partecipa in spazi/posizioni differenti di propria iniziativa, trovando soluzioni con efficacia e proponendole ai compagni.", "en": "The player participates in different spaces/positions on their own initiative, finding effective solutions and proposing them to teammates."}, "score": 4}]}, {"id": "a1_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a2_s", "type": "section", "title": {"es": "2. Referencias", "it": "2. Riferimenti", "en": "2. References"}, "description": {"es": "Reconocimiento de diferentes referencias de juego (compañeros, oponentes, balón, porterías, etc.) que ayudan a crear soluciones eficaces.", "it": "Riconoscimento di diversi riferimenti di gioco (compagni, avversari, pallone, porte, ecc.) che aiutano a creare soluzioni efficaci.", "en": "Recognition of different game references (teammates, opponents, ball, goals, etc.) that help create effective solutions."}}, {"id": "a2_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a2_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador no reconoce referencias de juego que puedan ayudarle a participar eficazmente.", "it": "Il giocatore non riconosce i riferimenti di gioco che possono aiutarlo a partecipare efficacemente.", "en": "The player does not recognise game references that could help them participate effectively."}, "score": 1}, {"id": "a2_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador empieza a reconocer algunas referencias de juego cuando le ayudan los entrenadores y/o compañeros, aportando a veces soluciones eficaces.", "it": "Il giocatore inizia a riconoscere alcuni riferimenti di gioco quando aiutato da allenatori e/o compagni, fornendo a volte soluzioni efficaci.", "en": "The player starts to recognise some game references when helped by coaches and/or teammates, sometimes providing effective solutions."}, "score": 2}, {"id": "a2_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador reconoce las diferentes referencias de juego con el apoyo ocasional de entrenadores y/o compañeros, tomando regularmente soluciones eficaces.", "it": "Il giocatore riconosce i diversi riferimenti di gioco con il supporto occasionale di allenatori e/o compagni, attuando regolarmente soluzioni efficaci.", "en": "The player recognises the different game references with occasional support from coaches and/or teammates, regularly choosing effective solutions."}, "score": 3}, {"id": "a2_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador reconoce las diferentes referencias de juego de forma autónoma, aportando incluso soluciones a sus compañeros, haciendo al equipo más imprevisible.", "it": "Il giocatore riconosce i diversi riferimenti di gioco in autonomia, fornendo persino soluzioni ai compagni, rendendo la squadra più imprevedibile.", "en": "The player recognises the different game references autonomously, even providing solutions to teammates and making the team more unpredictable."}, "score": 4}]}, {"id": "a2_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a3_s", "type": "section", "title": {"es": "3. Cooperación", "it": "3. Cooperazione", "en": "3. Cooperation"}, "description": {"es": "Participación y colaboración en el juego colectivo en función de la distancia al balón (a través de la intervención directa con el balón, posicionamiento, trayectorias, comunicación...).", "it": "Partecipazione e collaborazione nel gioco collettivo in base alla distanza dal pallone (tramite intervento diretto con la palla, posizionamento, traiettorie, comunicazione...).", "en": "Participation and collaboration in collective play depending on the distance to the ball (through direct involvement with the ball, positioning, runs, communication...)."}}, {"id": "a3_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a3_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador solo participa y colabora en el juego colectivo cuando está directamente implicado con el balón.", "it": "Il giocatore partecipa e collabora al gioco collettivo solo quando è direttamente coinvolto con il pallone.", "en": "The player only participates and collaborates in collective play when directly involved with the ball."}, "score": 1}, {"id": "a3_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador participa y colabora independientemente de la zona donde se encuentre el balón (a través de su posicionamiento, trayectorias o comunicación) al recibir instrucciones de entrenadores y/o compañeros.", "it": "Il giocatore partecipa e collabora indipendentemente dalla zona in cui si trova il pallone (tramite posizionamento, traiettorie o comunicazione) ricevendo istruzioni da allenatori e/o compagni.", "en": "The player participates and collaborates regardless of where the ball is (through positioning, runs or communication) when receiving instructions from coaches and/or teammates."}, "score": 2}, {"id": "a3_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador participa y colabora constantemente independientemente de la zona donde esté el balón, con el apoyo puntual de entrenadores y compañeros.", "it": "Il giocatore partecipa e collabora costantemente indipendentemente dalla zona in cui si trova il pallone, con il supporto puntuale di allenatori e compagni.", "en": "The player constantly participates and collaborates regardless of where the ball is, with occasional support from coaches and teammates."}, "score": 3}, {"id": "a3_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador participa y colabora constantemente, independientemente de la zona donde esté el balón, de forma autónoma, ayudando incluso a sus compañeros.", "it": "Il giocatore partecipa e collabora costantemente, indipendentemente dalla zona in cui si trova il pallone, in autonomia, aiutando persino i compagni.", "en": "The player constantly participates and collaborates, regardless of where the ball is, autonomously, even helping teammates."}, "score": 4}]}, {"id": "a3_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a4_s", "type": "section", "title": {"es": "4. Objetivos individuales", "it": "4. Obiettivi individuali", "en": "4. Individual goals"}, "description": {"es": "Identificar tus propias fortalezas y áreas de mejora, y seguir trabajando para desarrollarlas.", "it": "Identificare i propri punti di forza e le aree di miglioramento, continuando a lavorare per svilupparli.", "en": "Identify your own strengths and areas for improvement, and keep working to develop them."}}, {"id": "a4_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a4_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador no identifica sus fortalezas y/o áreas de mejora.", "it": "Il giocatore non identifica i propri punti di forza e/o le aree di miglioramento.", "en": "The player does not identify their strengths and/or areas for improvement."}, "score": 1}, {"id": "a4_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador identifica algunas fortalezas y áreas de mejora, pero su constancia en el entrenamiento es irregular; necesita ayuda de entrenadores y/o compañeros.", "it": "Il giocatore identifica alcuni punti di forza e aree di miglioramento, ma la sua costanza nell'allenamento è irregolare; ha bisogno dell'aiuto di allenatori e/o compagni.", "en": "The player identifies some strengths and areas for improvement, but their consistency in training is irregular; they need help from coaches and/or teammates."}, "score": 2}, {"id": "a4_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador es constante con sus objetivos, trabajando en sus áreas de mejora regularmente con el apoyo ocasional de entrenadores y/o compañeros.", "it": "Il giocatore è costante nei suoi obiettivi, lavorando regolarmente sulle aree di miglioramento con il supporto occasionale di allenatori e/o compagni.", "en": "The player is consistent with their goals, regularly working on areas for improvement with occasional support from coaches and/or teammates."}, "score": 3}, {"id": "a4_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador es autónomo en la gestión de sus objetivos, elabora su propio plan y estrategias de mejora, y ayuda incluso a sus compañeros.", "it": "Il giocatore è autonomo nella gestione dei propri obiettivi, sviluppa un proprio piano e strategie di miglioramento, aiutando persino i compagni.", "en": "The player manages their goals autonomously, builds their own improvement plan and strategies, and even helps teammates."}, "score": 4}]}, {"id": "a4_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a5_s", "type": "section", "title": {"es": "5. Comunicación", "it": "5. Comunicazione", "en": "5. Communication"}, "description": {"es": "Nivel de comunicación en aspectos relacionados con el juego y las emociones, verbalizado tanto en el campo como en dinámicas, actividades u otros espacios de entrenamiento.", "it": "Livello di comunicazione in aspetti legati al gioco e alle emozioni, verbalizzato sia in campo che in dinamiche, attività o altri spazi di allenamento.", "en": "Level of communication about the game and emotions, expressed both on the pitch and in group sessions, activities or other training settings."}}, {"id": "a5_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a5_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador evita comunicarse durante y fuera del juego con compañeros y/o entrenadores, sin compartir sus emociones y opiniones.", "it": "Il giocatore evita di comunicare durante e fuori dal gioco con compagni e/o allenatori, senza condividere emozioni e opinioni.", "en": "The player avoids communicating during and outside the game with teammates and/or coaches, without sharing emotions and opinions."}, "score": 1}, {"id": "a5_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador empieza a comunicarse ocasionalmente con compañeros y entrenadores, sin tener en cuenta las opiniones y emociones de los demás.", "it": "Il giocatore inizia a comunicare occasionalmente con compagni e allenatori, senza considerare le opinioni e le emozioni altrui.", "en": "The player starts to communicate occasionally with teammates and coaches, without taking others' opinions and emotions into account."}, "score": 2}, {"id": "a5_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador se comunica regularmente con compañeros y entrenadores, prestando atención a las opiniones y emociones de los demás.", "it": "Il giocatore comunica regolarmente con compagni e allenatori, prestando attenzione alle opinioni e alle emozioni altrui.", "en": "The player communicates regularly with teammates and coaches, paying attention to others' opinions and emotions."}, "score": 3}, {"id": "a5_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador se comunica constantemente con compañeros y entrenadores, comparte opiniones y emociones, y anima a los demás a hacer lo mismo.", "it": "Il giocatore comunica costantemente con compagni e allenatori, condivide opinioni ed emozioni, e incoraggia gli altri a fare lo stesso.", "en": "The player communicates constantly with teammates and coaches, shares opinions and emotions, and encourages others to do the same."}, "score": 4}]}, {"id": "a5_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a6_s", "type": "section", "title": {"es": "6. Entrenabilidad y aprendizaje", "it": "6. Allenabilità e apprendimento", "en": "6. Trainability and learning"}, "description": {"es": "Predisposición al aprendizaje y al entrenamiento que facilita la puesta en práctica de habilidades en diferentes contextos vividos (dinámicas, tareas, competición...).", "it": "Predisposizione all'apprendimento e all'allenamento che facilita l'applicazione di abilità in diversi contesti vissuti (dinamiche, compiti, competizione...).", "en": "Willingness to learn and train that makes it easier to apply skills in different contexts (group sessions, drills, competition...)."}}, {"id": "a6_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a6_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador muestra poca disposición a entrenar y aprender, y tiene dificultades para poner en práctica nuevas habilidades.", "it": "Il giocatore mostra scarsa disposizione ad allenarsi e imparare, e ha difficoltà a mettere in pratica nuove abilità.", "en": "The player shows little willingness to train and learn, and struggles to put new skills into practice."}, "score": 1}, {"id": "a6_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador muestra disposición a entrenar y aprender, aunque tiene dificultades para poner en práctica nuevas habilidades y necesita ayuda constante de entrenadores y/o compañeros.", "it": "Il giocatore mostra disposizione ad allenarsi e imparare, sebbene abbia difficoltà a mettere in pratica nuove abilità e necessiti di aiuto costante da parte di allenatori e/o compagni.", "en": "The player is willing to train and learn, although they struggle to put new skills into practice and need constant help from coaches and/or teammates."}, "score": 2}, {"id": "a6_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador muestra disposición a entrenar y aprender, poniendo en práctica nuevas habilidades con el apoyo ocasional de entrenadores y/o compañeros.", "it": "Il giocatore mostra disposizione ad allenarsi e imparare, mettendo in pratica nuove abilità con il supporto occasionale di allenatori e/o compagni.", "en": "The player is willing to train and learn, putting new skills into practice with occasional support from coaches and/or teammates."}, "score": 3}, {"id": "a6_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador muestra disposición a entrenar y aprender, poniendo en práctica nuevas habilidades de forma autónoma e incluso ayudando a los demás.", "it": "Il giocatore mostra disposizione ad allenarsi e imparare, mettendo in pratica nuove abilità in autonomia e aiutando persino gli altri.", "en": "The player is willing to train and learn, putting new skills into practice autonomously and even helping others."}, "score": 4}]}, {"id": "a6_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a7_s", "type": "section", "title": {"es": "7. Resiliencia", "it": "7. Resilienza", "en": "7. Resilience"}, "description": {"es": "La capacidad de afrontar situaciones difíciles (errores en el juego, falta de minutos de juego, lesiones, problemas familiares, etc.) y encontrar soluciones para superarlas.", "it": "La capacità di affrontare situazioni difficili (errori di gioco, mancanza di minutaggio, infortuni, problemi familiari, ecc.) e trovare soluzioni per superarle.", "en": "The ability to face difficult situations (mistakes in the game, lack of playing time, injuries, family problems, etc.) and find solutions to overcome them."}}, {"id": "a7_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a7_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador utiliza excusas en situaciones difíciles (errores en el juego, sustituciones, lesiones, problemas familiares...).", "it": "Il giocatore usa scuse in situazioni difficili (errori di gioco, sostituzioni, infortuni, problemi familiari...).", "en": "The player makes excuses in difficult situations (mistakes in the game, substitutions, injuries, family problems...)."}, "score": 1}, {"id": "a7_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador afronta situaciones difíciles, encontrando soluciones con la ayuda de entrenadores y/o compañeros.", "it": "Il giocatore affronta situazioni difficili, trovando soluzioni con l'aiuto di allenatori e/o compagni.", "en": "The player faces difficult situations, finding solutions with the help of coaches and/or teammates."}, "score": 2}, {"id": "a7_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador supera situaciones difíciles, encontrando soluciones con regularidad y con el apoyo puntual de entrenadores y compañeros.", "it": "Il giocatore supera situazioni difficili, trovando regolarmente soluzioni con il supporto puntuale di allenatori e compagni.", "en": "The player overcomes difficult situations, regularly finding solutions with occasional support from coaches and teammates."}, "score": 3}, {"id": "a7_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador da la vuelta a situaciones difíciles, encontrando soluciones de forma autónoma e influyendo en compañeros y entrenadores.", "it": "Il giocatore ribalta situazioni difficili, trovando soluzioni in autonomia e influenzando compagni e allenatori.", "en": "The player turns difficult situations around, finding solutions autonomously and influencing teammates and coaches."}, "score": 4}]}, {"id": "a7_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a8_s", "type": "section", "title": {"es": "8. Cohesión y liderazgo", "it": "8. Coesione e leadership", "en": "8. Cohesion and leadership"}, "description": {"es": "Contribución al desarrollo de las relaciones entre los miembros del grupo participando activamente como elemento cohesivo del equipo.", "it": "Contributo allo sviluppo delle relazioni tra i membri del gruppo partecipando attivamente come elemento di coesione della squadra.", "en": "Contribution to developing relationships among group members by actively taking part as a cohesive element of the team."}}, {"id": "a8_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a8_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "El jugador no participa con el grupo o entorpece las relaciones con comportamientos inadecuados.", "it": "Il giocatore non partecipa con il gruppo o ostacola le relazioni con comportamenti inadeguati.", "en": "The player does not take part with the group or hinders relationships with inappropriate behaviour."}, "score": 1}, {"id": "a8_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador participa con el grupo ocasionalmente, aunque necesita el apoyo constante de entrenadores y compañeros para comprender su impacto en los demás.", "it": "Il giocatore partecipa con il gruppo occasionalmente, sebbene abbia bisogno del supporto costante di allenatori e compagni per comprendere il proprio impatto sugli altri.", "en": "The player occasionally takes part with the group, although they need constant support from coaches and teammates to understand their impact on others."}, "score": 2}, {"id": "a8_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador es participativo y contribuye a las relaciones entre los miembros del grupo, solicitando un apoyo ocasional a entrenadores y compañeros.", "it": "Il giocatore è partecipativo e contribuisce alle relazioni tra i membri del gruppo, richiedendo un supporto occasionale ad allenatori e compagni.", "en": "The player is engaged and contributes to relationships among group members, asking coaches and teammates for occasional support."}, "score": 3}, {"id": "a8_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador toma la iniciativa a través de acciones que contribuyen a las relaciones entre los miembros del grupo.", "it": "Il giocatore prende l'iniziativa attraverso azioni che contribuiscono alle relazioni tra i membri del gruppo.", "en": "The player takes the initiative through actions that contribute to relationships among group members."}, "score": 4}]}, {"id": "a8_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}, {"id": "a9_s", "type": "section", "title": {"es": "9. Hábitos de vida", "it": "9. Stili di vita", "en": "9. Lifestyle habits"}, "description": {"es": "Rutinas y comportamientos que promueven el bienestar general y el rendimiento óptimo (salud física y mental, descanso, nutrición, hidratación, higiene, salud, ocio...).", "it": "Routine e comportamenti che promuovono il benessere generale e le prestazioni ottimali (salute fisica e mentale, riposo, nutrizione, idratazione, igiene, salute, tempo libero...).", "en": "Routines and behaviours that promote general well-being and optimal performance (physical and mental health, rest, nutrition, hydration, hygiene, health, leisure...)."}}, {"id": "a9_lvl", "type": "single_choice", "required": true, "title": {"es": "Nivel", "it": "Livello", "en": "Level"}, "options": [{"id": "a9_l1", "label": {"es": "Nivel 1", "it": "Livello 1", "en": "Level 1"}, "description": {"es": "Los hábitos de vida del jugador son perjudiciales y desconoce cómo esto afecta a su rendimiento y a su salud física y/o mental.", "it": "Le abitudini di vita del giocatore sono nocive ed egli ignora come ciò influisca sulle sue prestazioni e sulla salute fisica e/o mentale.", "en": "The player's lifestyle habits are harmful and they don't know how this affects their performance and physical and/or mental health."}, "score": 1}, {"id": "a9_l2", "label": {"es": "Nivel 2", "it": "Livello 2", "en": "Level 2"}, "description": {"es": "El jugador sabe qué cambios debe realizar en sus hábitos de vida, aunque no los desarrolla en la práctica ni los mantiene con regularidad.", "it": "Il giocatore sa quali cambiamenti dovrebbe apportare alle proprie abitudini di vita, sebbene non li metta in pratica né li mantenga regolarmente.", "en": "The player knows what changes to make to their lifestyle habits, although they don't put them into practice or keep them up regularly."}, "score": 2}, {"id": "a9_l3", "label": {"es": "Nivel 3", "it": "Livello 3", "en": "Level 3"}, "description": {"es": "El jugador mantiene hábitos de vida saludables de forma regular, requiriendo supervisión ocasional para consolidarlos.", "it": "Il giocatore mantiene abitudini di vita sane con regolarità, richiedendo una supervisione occasionale per consolidarle.", "en": "The player regularly maintains healthy lifestyle habits, needing occasional supervision to consolidate them."}, "score": 3}, {"id": "a9_l4", "label": {"es": "Nivel 4", "it": "Livello 4", "en": "Level 4"}, "description": {"es": "El jugador pone en práctica de forma autónoma hábitos saludables, informándose, consultando y aplicando diferentes estrategias que intenta trasladar al grupo.", "it": "Il giocatore mette in pratica autonomamente abitudini sane, informandosi, consultando e applicando diverse strategie che cerca di trasferire al gruppo.", "en": "The player autonomously puts healthy habits into practice, researching, asking and applying different strategies they try to pass on to the group."}, "score": 4}]}, {"id": "a9_ref", "type": "long_text", "title": {"es": "Reflexión", "it": "Riflessione", "en": "Reflection"}, "description": {"es": "Puedes compartir cualquier reflexión que consideres importante. Sugerencias para trabajar, qué dificultades encuentras, qué te ayuda...", "it": "Puoi condividere qualsiasi riflessione tu ritenga importante. Suggerimenti per lavorare, quali difficoltà incontri, cosa ti aiuta...", "en": "Share any reflection you consider important. Suggestions to work on, difficulties you face, what helps you..."}}]$json$::jsonb, 'draft')
